import { readFileSync } from 'node:fs';
import { UpstreamError } from './errors.js';

// Root-level resource types of the Fusion graph model (generated by scripts/extract-root-resources.mjs).
export const ROOTS = JSON.parse(readFileSync(new URL('./root-resources.json', import.meta.url), 'utf8')).map((r) => ({
    name: r.name,
    label: r.friendlyName || r.name,
    description: r.description || '',
}));
export const ROOT_NAMES = new Set(ROOTS.map((r) => r.name));

/**
 * How many resources each root type has, or why it can't be listed. Returns
 * { [name]: { total } | { total: null } | { error, status } }.
 *
 * Most types answer `page[totals]` with a count. Some polymorphic ones (CORS Rule, Auth Rule, ...) reject that
 * parameter with a 400 but list fine, so on a 400 we retry without it: the type stays usable with an unknown count
 * (`total: null`). Only a type that can't be listed at all (404, 500) is reported as an error.
 */
export async function countRoots(fetchConfig, { concurrency = 6, signal } = {}) {
    const counts = {};
    const queue = ROOTS.map((r) => r.name);
    await Promise.all(
        Array.from({ length: concurrency }, async () => {
            while (queue.length) {
                signal?.throwIfAborted();
                const name = queue.shift();
                const path = `/${encodeURIComponent(name)}?page[size]=1`;
                try {
                    try {
                        const doc = await fetchConfig(`${path}&page[totals]`);
                        counts[name] = { total: doc.meta?.page?.totalRecords ?? (Array.isArray(doc.data) ? doc.data.length : 0) };
                    } catch (err) {
                        if (!(err instanceof UpstreamError) || err.status !== 400) throw err;
                        await fetchConfig(path); // listable, just not countable
                        counts[name] = { total: null };
                    }
                } catch (err) {
                    if (!(err instanceof UpstreamError) || err.status === 401) throw err;
                    counts[name] = { error: err.message, status: err.status };
                }
            }
        })
    );
    return counts;
}
